  loading:     false,
  selectedRow: null as RowItem | null,
  pageSize:    20,
  page:        { first: 0, rows: 20 },
});

const searchParams = reactive({
  deptNm: '',
  oblgLawNm: '',
  riskGrdCd: '',
  endYn: '',
  asmtDtRangeFrom: '',
  asmtDtRangeTo: '',
});

// ─────────────────── Computed ───────────────────────────────────────────────────────
const filteredRows = computed<RowItem[]>(() => {
  let rows = allRows.value;
  if (searchParams.deptNm) rows = rows.filter(r => r.deptNm.includes(searchParams.deptNm));
  if (searchParams.oblgLawNm) rows = rows.filter(r => r.oblgLawNm.includes(searchParams.oblgLawNm));
  if (searchParams.riskGrdCd) rows = rows.filter(r => r.riskGrdCd === searchParams.riskGrdCd);
  if (searchParams.endYn) rows = rows.filter(r => r.endYn === searchParams.endYn);
  if (searchParams.asmtDtRangeFrom) rows = rows.filter(r => r.asmtDtRange >= searchParams.asmtDtRangeFrom);
  if (searchParams.asmtDtRangeTo)   rows = rows.filter(r => r.asmtDtRange <= searchParams.asmtDtRangeTo);
  return rows;
});

const pagedRows = computed<RowItem[]>(() =>
  filteredRows.value.slice(state.page.first, state.page.first + state.pageSize)
);

